    qs.push({n:17,title:'Algorithm design',stimulus:`An array named Scores contains ten integer risk scores. The program must calculate their total and display "High" for a total over 35, "Low" for a total below 20, and "Medium" otherwise.`,parts:[{id:'a',...written('Construct pseudocode using iteration and selection to produce the correct rating.',3,90,'total ← 0\nFOR each score IN Scores\n    total ← total + score\nENDFOR\nIF total > 35 THEN\n    DISPLAY "High"\nELSEIF total < 20 THEN\n    DISPLAY "Low"\nELSE\n    DISPLAY "Medium"\nENDIF',[criterion('Initialises and accumulates a running total','total|sum'),criterion('Includes an iteration over scores','for|while|repeat|iterate|loop'),criterion('Correctly branches on both numeric boundaries and displays category','35','20','high|low|medium')])}]});
    qs.push({n:18,title:'Metadata and data mining',stimulus:`A ${c.entity} receives a high volume of website requests during scheduled announcements. It collects timestamps, request outcomes, device types and peak audience counts.`,parts:[{id:'a',...written('Explain how metadata and data mining can help prevent technical difficulties during peak demand.',3,85,'Metadata such as request timestamps, location or device type describes usage events. Mining historical access patterns can reveal likely peak load and common error patterns. The service can respond by scheduling extra server capacity, optimising its cache and testing likely bottlenecks before anticipated demand.',[criterion('Identifies relevant metadata','metadata|timestamp|device|request|time|location'),criterion('Explains pattern discovery through data mining','mining|pattern|trend|analys|predict|forecast'),criterion('Links findings to operational prevention','capacity|scale|load balanc|server|cache|bottleneck|allocat|prevent|latenc')])}]});
