    qs.push({n:22,title:'Object-oriented class modelling',stimulus:`The platform models ${c.diagram[1]}, ${c.diagram[2]} and ${c.diagram[3]}. All of these share an identifier and a creation date. Each also has specialist attributes.`,parts:[{id:'a',type:'diagram',marks:3,prompt:'Construct a class diagram that removes duplicated attributes using a superclass and inheritance links. Add at least four class boxes and identify suitable attributes.',wordGuide:0,diagram:{names:c.diagram,common:['id: int','createdAt: datetime'],specific:{[c.diagram[1]]:['status: str'],[c.diagram[2]]:['priority: int'],[c.diagram[3]]:['region: str']}},sample:`${c.diagram[0]} (id, createdAt)\n  ↑ ${c.diagram[1]} (status)\n  ↑ ${c.diagram[2]} (priority)\n  ↑ ${c.diagram[3]} (region)`}]});
